fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // If maxsplit is 0, no splitting is performed; just wrap each string in a single-element vector.
    if maxsplit == 0 {
        return a.into_iter().map(|s| vec![s]).collect();
    }

    let maxsplit_usize = maxsplit as usize;

    a.into_iter()
        .map(|s| {
            if s.is_empty() {
                // If input string is empty, return a vec with one empty string as required
                vec![String::new()]
            } else {
                // Perform right split with a maxsplit limit
                // The standard library split method can be reversed and limited for this.
                // Using rsplit to split from the right
                let parts: Vec<String> = s
                    .rsplit(&sep)
                    .take(maxsplit_usize + 1)
                    .map(|part| part.to_string())
                    .collect();

                // rsplit returns parts in reverse order, so reverse to preserve correct order
                let mut parts = parts.into_iter().rev().collect::<Vec<_>>();
                parts
            }
        })
        .collect()
}